import{_ as i,o as a,c as t,a2 as n}from"./chunks/framework.XWkMPaqj.js";const c=JSON.parse('{"title":"重比对概述","description":"","frontmatter":{"title":"重比对概述","order":6},"headers":[],"relativePath":"realignment/overview.md","filePath":"realignment/overview.md"}'),o={name:"realignment/overview.md"};function r(l,e,s,m,d,h){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="重比对概述" tabindex="-1">重比对概述 <a class="header-anchor" href="#重比对概述" aria-label="Permalink to &quot;重比对概述&quot;">​</a></h1><p>The progressive method is employed in most multiple sequence alignment tools but based on the rule of “Once a gap, always a gap,” wrong insertions will remain in the output, impacting the accuracy of the final alignment.</p><p><strong>Realignment methods, sometimes also considered refinement methods, which choose sequences or blocks of existing alignments and realign in the hopes that the realigned result is more accurate.</strong></p><p>Both <strong>the realigner</strong> and the <strong>post-processing of some MSA tools</strong> utilize the realignment method, and here we summarize it by <strong>partitioning</strong>. In addition, the realignment methods <strong>often (do not always)</strong> combine with iterative methods. <strong>The five commonly iterative methods are:</strong></p><ol><li>Round-robin(RR) iterative algorithm</li><li>Remove First(RF) iterative algorithm</li><li>Best First(BF) iterative algorithm</li><li>Random(RD) iterative algorithm</li><li>Tree-based(TB) iterative algorithm</li></ol><h2 id="realigners-based-on-vertical-partitioning" tabindex="-1"><a href="./standalone.html#vertical">Realigners based on vertical partitioning</a> <a class="header-anchor" href="#realigners-based-on-vertical-partitioning" aria-label="Permalink to &quot;[Realigners based on vertical partitioning](standalone.md#vertical)&quot;">​</a></h2><p>Summary of the realigners based on vertical partitioning.</p><p>There are tow restricted vertical partitioning (column-oriented partitioning):</p><ol><li>Gap-based partitioning</li><li>Whole same column-based partitioning</li></ol><h2 id="realigners-based-on-horizontal-partitioning" tabindex="-1"><a href="./standalone.html#horizontal">Realigners based on horizontal partitioning</a> <a class="header-anchor" href="#realigners-based-on-horizontal-partitioning" aria-label="Permalink to &quot;[Realigners based on horizontal partitioning](standalone.md#horizontal)&quot;">​</a></h2><p>Summary of the realigners based on horizontal partitioning.</p><p>There are three restricted horizontal partitioning (row-oriented partitioning):</p><ol><li>Single-type partitioning</li><li>Double-type partitioning</li><li>Tree-dependent partitioning</li></ol><h2 id="realigners-based-on-vertical-and-horizontal-partitioning" tabindex="-1"><a href="./standalone.html#combined">Realigners based on vertical and horizontal partitioning</a> <a class="header-anchor" href="#realigners-based-on-vertical-and-horizontal-partitioning" aria-label="Permalink to &quot;[Realigners based on vertical and horizontal partitioning](standalone.md#combined)&quot;">​</a></h2><p>Summary of the realigners based on vertical and horizontal partitioning.</p><h2 id="realignment-in-msa-tools" tabindex="-1">Realignment in MSA tools <a class="header-anchor" href="#realignment-in-msa-tools" aria-label="Permalink to &quot;Realignment in MSA tools&quot;">​</a></h2><p>Summary of the realignment post-processing in MSA tools.</p><h3 id="vertical-oriented-realignment-in-msa-tools" tabindex="-1"><a href="./in-msa.html#vertical">Vertical-oriented realignment in MSA tools</a> <a class="header-anchor" href="#vertical-oriented-realignment-in-msa-tools" aria-label="Permalink to &quot;[Vertical-oriented realignment in MSA tools](in-msa.md#vertical)&quot;">​</a></h3><h3 id="horizontal-oriented-realignment-in-msa-tools" tabindex="-1"><a href="./in-msa.html#horizontal">Horizontal-oriented realignment in MSA tools</a> <a class="header-anchor" href="#horizontal-oriented-realignment-in-msa-tools" aria-label="Permalink to &quot;[Horizontal-oriented realignment in MSA tools](in-msa.md#horizontal)&quot;">​</a></h3><ol><li>Random partitioning (ProbCons / MSAProbs / MSACompro / GLProbs / QuickProbs / PnpProbs)</li><li>Single-type partitioning (MLAGAN / MANGO)</li><li>Tree-dependent partitioning (MUSCLE / MAFFT / PRIME / PRALINE / PAAA / Javad Sadri&#39;s work / Motalign)</li></ol><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><ol><li>Gotoh, Osamu. &quot;Optimal alignment between groups of sequences and its application to multiple sequence alignment.&quot; Bioinformatics 9.3 (1993): 361-370.</li><li>Hirosawa, Makoto, et al. &quot;Comprehensive study on iterative algorithms of multiple sequence alignment.&quot; Bioinformatics 11.1 (1995): 13-18.</li><li>Wallace, Iain M., and Desmond G. Higgins. &quot;Evaluation of iterative alignment algorithms for multiple alignment.&quot; Bioinformatics 21.8 (2005): 1408-1414.</li><li>Wakatsu, Daigo, and Takeo Okazaki. &quot;Statistical Comparative Study of Multiple Sequence Alignment Scores of Iterative Refinement Algorithms.&quot; IPSJ Transactions on Bioinformatics 2 (2009): 74-82.</li><li>DeBlasio, Dan, and John Kececioglu. Parameter advising for multiple sequence alignment. Vol. 26. Springer, 2018.</li></ol>',22)])])}const p=i(o,[["render",r]]);export{c as __pageData,p as default};
